input.function:
() => {
  const inputs = document.querySelectorAll('input');
  const setVal = (el, v) => {
    const proto = el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
    setter.call(el, v);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  };
  if (inputs.length >= 2) {
    setVal(inputs[0], 'analyst1');
    setVal(inputs[1], 'test123');
    return 'filled ' + inputs.length + ' inputs: ' + inputs[0].value + ' / ' + (inputs[1].value ? '***' : 'EMPTY');
  }
  return 'inputs found: ' + inputs.length;
}

() => {
  // 暂停所有 CSS 动画/过渡，停止 video/canvas 动画
  const style = document.createElement('style');
  style.id = '__freeze_anim';
  style.textContent = '* { animation-play-state: paused !important; transition: none !important; }';
  document.head.appendChild(style);
  document.querySelectorAll('video').forEach(v => v.pause());
  return 'animations frozen';
}
